<?php $base='/research/'.$r['slug'];$meta=json_decode($result['metadata'],true);$admission=$result['admission'];$held=$admission==='quarantined';$rejected=$admission==='rejected';$receiptTitle=$held?'Packet quarantined — awaiting admin':($rejected?'Packet rejected':'Submission accepted'); ?>
<div class="workflow-heading"><a class="back" href="<?=e($base)?>/work">← Research workflow</a><h1><?=e($receiptTitle)?></h1><p><?=e(ar_method($result['submission_method']))?> · <span class="<?=$admission==='accepted'?'status':'influence-badge'?>"><?=e($admission==='accepted'?$result['outcome']:'Not applied')?></span><?php if(($meta['human_influence']['review_status']??'')==='needed'): ?> <strong class="influence-badge">Admin decision required</strong><?php elseif(($meta['human_influence']['review_status']??'')==='approved'): ?> <strong class="status">Approved by admin</strong><?php endif ?> · <?=e($result['created_at'])?> UTC</p><div class="actions primary-actions"><a class="button" href="<?=e($base)?>/work"><?=e($held?'View research status':($rejected?'Get a fresh handoff':'See next available work'))?></a><a class="button secondary" href="<?=e($base)?>/ledger">UTC ledger</a><a class="button secondary" href="<?=e($base)?>/packages/<?=e($result['snapshot_id'])?>">Context used for this run</a><?php if($admission==='accepted'&&!empty($meta['evidence']['calculations'])): try{rc_read($r['id'],$result['id']);$downloadCurrent=true;}catch(HttpError){$downloadCurrent=false;}if($downloadCurrent): foreach($meta['evidence']['calculations'] as $calculationIndex=>$calculationLink): ?><a class="button secondary" href="<?=e($base)?>/results/<?=e($result['id'])?>/calculations/<?=e($calculationLink['id'])?>/bundle.json">Calculation files<?=count($meta['evidence']['calculations'])>1?' '.($calculationIndex+1):''?></a><?php endforeach;endif;endif ?><?php if($admission==='accepted'&&!empty($meta['evidence']['tool_builds'])): ?><a class="button secondary" href="#tool-builds">Tool files &amp; tests</a><?php endif ?></div></div>

<?php include __DIR__.'/workflow-verification.php'; ?>
<?php if($held||$rejected): ?><p class="warning" role="status"><?=e($held?'Received, not accepted. Research is paused until an administrator approves or rejects this packet. You do not need to resubmit it.':'This packet was not applied to the research. Start a fresh AI conversation with a new handoff and avoid steering the conclusion. The original packet and admin reason remain in the audit history.')?></p><?php endif ?><?php if(isset($meta['human_influence']['review_reason'])): ?><aside class="notice"><strong>Admin decision · <?=e($meta['human_influence']['reviewed_at_utc'])?> UTC</strong><p><?=e($meta['human_influence']['review_reason'])?></p></aside><?php endif ?><section class="task-brief result-conclusion"><h2><?=e($admission==='accepted'?'Conclusion':'Submitted conclusion — not accepted evidence')?></h2><?=prose($result['reason'])?><p><strong>Current research status:</strong> <?=e($r['status'])?>. <?=e($admission==='accepted'?'This result is accepted and recorded.':'This packet has not advanced research.')?></p><details><summary>AI-proposed next steps (written before submission)</summary><?=prose($result['next_action'])?></details><p class="fine">Only accepted packets can advance research; quarantined and rejected packets are excluded from AI evidence packages. Submission method is declared, not proof of AI authorship, conversation integrity, scientific truth or verified identity.</p></section>
<?php if($admission==='accepted'){$citationResult=$result;include __DIR__.'/citation.php';} ?>
<?php $influence=$meta['human_influence']??null;include __DIR__.'/workflow-influence.php';include __DIR__.'/workflow-evidence.php';include __DIR__.'/workflow-artifacts.php';include __DIR__.'/workflow-calculations.php';include __DIR__.'/workflow-tools.php'; ?>
<section><?php foreach(['body'=>'Full result','methodology'=>'How it was investigated','sources'=>'Sources & search record','limitations'=>'Limitations'] as $key=>$label): ?><h3><?=e($label)?></h3><?=prose($result[$key])?><?php endforeach ?>
<?php if($result['plan_json']!=='[]'): ?><h3>Submitted task plan</h3><?php foreach(json_decode($result['plan_json'],true) as $planned): ?><article class="task-brief"><h4><?=e($planned['title'])?></h4><?=prose($planned['objective'])?><p><strong>Deliverable:</strong> <?=e($planned['deliverable'])?></p><p><strong>Acceptance:</strong> <?=e($planned['acceptance'])?></p><?php if(isset($planned['evidence_needs'])): ?><p><strong>Evidence needs:</strong> <?=e($planned['evidence_needs'])?></p><p><strong>Stopping rule:</strong> <?=e($planned['stopping_rule'])?></p><?php endif ?><p class="fine">Task key <?=e($planned['key'])?> · Dependencies: <?=e(implode(', ',$planned['dependencies'])?:'None')?></p></article><?php endforeach; endif ?><h3>Who / how</h3><p><?=e($result['display_name']?:'Anonymous volunteer')?> · identity unverified</p><dl class="metadata"><?php foreach($meta as $key=>$value): if(in_array($key,['acceptance_checks','corrections','human_influence','verification','evidence'],true))continue; ?><dt><?=e($key)?></dt><dd><?=e(is_array($value)?json_encode($value,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES):$value)?></dd><?php endforeach ?></dl><p><a href="<?=e($base)?>/tasks/<?=e($result['task_id'])?>">Affected task</a> · Result <?=e($result['id'])?></p></section>
